<script setup lang="ts">
import {ref,computed,watch,onMounted,onUnmounted,nextTick} from 'vue';
import {post,safeOfficialUrl,safeArticleUrl} from './api/client';
import {stream} from './composables/stream';
import FactEngineDesk from './components/FactEngineDesk.vue';
import WatchUpdates from './components/WatchUpdates.vue';
import ImportantEvents from './components/ImportantEvents.vue';
import FinancialWorkbench from './components/FinancialWorkbench.vue';
import VirtualEvents from './components/VirtualEvents.vue';
import EventReadState from './components/EventReadState.vue';
import ResearchDesk from './components/ResearchDesk.vue';
import BrowserObservation from './components/BrowserObservation.vue';
import GovernanceDesk from './components/GovernanceDesk.vue';
import PracticalDesk from './components/PracticalDesk.vue';import {useRoute,useRouter} from 'vue-router';import {navigation} from './router';import {title,sourceName,utc,http,duration} from './presentation/zh';
const route=useRoute(),router=useRouter(),menuOpen=ref(false);
import MarketLinkage from './components/MarketLinkage.vue';import TransmissionDesk from './components/TransmissionDesk.vue';
type Row=Record<string,any>;
const menus=navigation.map(([name])=>name);const unavailable=['全球产业情报','风险预警中心'];
const active=ref('全球实时情报'),token=ref(''),connected=ref(false),busy=ref(false),error=ref(''),status=ref('未连接'),events=ref<Row[]>([]),sources=ref<Row[]>([]),stats=ref<Row>({}),evidence=ref<Row[]>([]),search=ref(''),source=ref(''),page=ref(0),total=ref(0),auto=ref(true),pending=ref(0),secStatus=ref<Row>({}),secSearch=ref(''),secCompanies=ref<Row[]>([]);
const queryStatus=ref('正在连接');
const macroChangesAvailable=['5179','5180'].includes(location.port);const transmissionAvailable=location.port==='5180';
const practicalMode=computed(()=>['全球官方发布监控','金融事件研判','全球宏观监测','每日金融简报','数据源监控','系统设置'].includes(active.value));
const localAuto=['5173','5176'].includes(location.port);
async function selectMenu(menu:string){menuOpen.value=false;await router.push(navigation.find(([name])=>name===menu)![1]);}
watch(()=>route.path,()=>{active.value=String(route.meta.title||'全球实时情报');document.title='寰瞰 · '+active.value;evidence.value=[];if(['全球实时情报','待核线索','全球企业公告','数据溯源中心'].includes(active.value)){source.value=active.value==='待核线索'?'GDELT':active.value==='全球企业公告'?'SEC':'';page.value=0;if(connected.value)void query();}});
onMounted(()=>{active.value=String(route.meta.title||'全球实时情报');document.title='寰瞰 · '+active.value;if(active.value==='全球企业公告')source.value='SEC';if(active.value==='待核线索')source.value='GDELT';if(localAuto)void login();});
const alerts=ref<Row[]>([]),fredStatus=ref<Row>({});
async function acknowledge(receipts:unknown){for(let attempt=0;attempt<3;attempt++){try{await post('/stream/ack-batch',token.value,receipts);return;}catch{if(attempt===2){error.value='部分推送接收确认未记录，不能计为完整交付';return;}await new Promise(r=>setTimeout(r,500*(attempt+1)));}}}

let browserClock:{offset:number;uncertainty:number}|undefined;
async function calibrateBrowserClock(){try{const started=performance.now(),epoch=Date.now();const result=await post<{serverTime:string}>('/stream/browser/clock',token.value);const elapsed=performance.now()-started;browserClock={offset:Date.parse(result.serverTime)-(epoch+elapsed/2),uncertainty:elapsed/2};}catch{browserClock=undefined;}}
async function observeBrowser(notices:import('./composables/stream').Notice[]){await nextTick();await new Promise<void>(resolve=>requestAnimationFrame(()=>resolve()));const receipts=notices.map(n=>{const element=document.querySelector('[data-event-id="'+n.data.event_id+'"]');const rect=element?.getBoundingClientRect();const rendered=!!rect&&rect.width>0&&rect.height>0&&rect.top<innerHeight&&rect.bottom>0;return {deliveryId:n.data.delivery_id,connectionId:n.data.connection_id,eventId:n.data.event_id,receivedAt:n.data.client_received_at,receivedMonotonicMs:n.data.received_monotonic_ms,renderedAt:rendered?new Date().toISOString():null,renderMonotonicMs:rendered?performance.now():null,clockOffsetMs:browserClock?.offset??null,clockUncertaintyMs:browserClock?.uncertainty??null};});for(let i=0;i<3;i++){try{await post('/stream/browser/ack',token.value,receipts);return;}catch{await new Promise(r=>setTimeout(r,500*(i+1)));}}error.value='浏览器渲染观测未记录，不能计为完整在线传播';}

const watchOnly=ref(false);
const subscriptionScope=ref('OFFICIAL'),subscriptionSource=ref(''),subscriptionPriority=ref(0);
const eventViewport=ref<InstanceType<typeof VirtualEvents>>();
const region=ref(''),category=ref(''),sort=ref('official'),autoScroll=ref(false);
let abort:AbortController|undefined;
const time=(v:unknown)=>v?new Date(String(v)).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'未提供';
const verified=(v:string)=>({VERIFIED:'官方来源证据确认',PENDING:'待核验',QUARANTINED:'已隔离'}[v]||'核验状态待确认');
async function refresh(){const [list,s,st]=await Promise.all([post<{items:Row[];total:number}>('/events/query',token.value,{search:search.value,source:source.value,page:page.value,region:region.value,category:category.value,sort:sort.value}),post<Row[]>('/sources/query',token.value),post<Row>('/stats',token.value)]);events.value=list.items;total.value=list.total;sources.value=s;stats.value=st;alerts.value=await post<Row[]>('/monitor/alerts',token.value);}
async function query(){busy.value=true;error.value='';try{await refresh();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function login(){try{const initial=await post<{cursor:string}>('/stream/cursor',token.value);await query();if(error.value){if(!connected.value){queryStatus.value='实时连接已断开';status.value='实时连接已断开';}return;}connected.value=true;void calibrateBrowserClock();abort?.abort();abort=new AbortController();void stream(token.value,abort.signal,async allNotices=>{const notices=allNotices.filter(n=>!n.data.checkpoint);if(!notices.length)return;const receipts=notices.filter(n=>n.data.delivery_id).map(n=>({deliveryId:n.data.delivery_id,receivedAt:n.data.client_received_at}));if(receipts.length)void acknowledge(receipts);if(auto.value){await refresh();pending.value=0;if(autoScroll.value){await nextTick();eventViewport.value?.scrollStart();}}else pending.value+=notices.filter(n=>n.data.delivery_type==='LIVE'||n.data.qualification_update===true&&n.data.important_alert_eligible===true&&n.data.replay_flag!==true).length;await observeBrowser(notices);},s=>status.value=s,initial.cursor,subscriptionScope.value,subscriptionSource.value,subscriptionPriority.value,watchOnly.value);secStatus.value=await post<Row>('/sec/status',token.value);fredStatus.value=await post<Row>('/fred/status',token.value);}catch(e){error.value=(e as Error).message;if(!connected.value){queryStatus.value='实时连接已断开';status.value='实时连接已断开';}}}
async function secAction(path:string,body:unknown={}){try{const result=await post<Row[]>('/sec/'+path,token.value,body);if(path==='companies/search')secCompanies.value=result;secStatus.value=await post<Row>('/sec/status',token.value);fredStatus.value=await post<Row>('/fred/status',token.value);}catch(e){error.value=(e as Error).message;}}
const kind=(v:string)=>({HISTORICAL_BACKFILL:'历史消息（历史回填）',NEW_EVENT:'监控期间新增',REVISION:'资料修订'}[v]||'待核验');
const freshness=(event:Row)=>event.ingestion_kind==='HISTORICAL_BACKFILL'?'历史记录':!event.published_at?'官方发布时间未知':Date.now()-new Date(event.published_at).getTime()>86400000?'已发布超过24小时':'近期发布';
const availability=(v:string)=>({NOT_PUBLISHED:'尚未发布',PUBLISHED_NOT_AVAILABLE:'已公布，等待文件可下载',MISSING_HISTORICAL_BATCH:'历史批次缺失，等待补采',TRANSIENT_HTTP_FAILURE:'网络暂时失败，等待重试',PERMANENT_FAILURE:'校验、访问或重试预算规则阻止自动恢复',AVAILABLE:'文件已获取'}[v]||'尚未检查');
const jobState=(v:string)=>({SUCCESS:'成功',FAILED:'失败',RUNNING:'运行中'}[v]||'尚未运行');
async function details(id:string){try{evidence.value=await post<Row[]>('/events/'+id+'/evidence',token.value);}catch(e){error.value=(e as Error).message;}}
async function collect(id:string){busy.value=true;try{await post('/sources/collect',token.value,{source:id});await refresh();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function logout(){abort?.abort();token.value='';connected.value=false;events.value=[];sources.value=[];stats.value={};evidence.value=[];status.value='未连接';}
const monitorTimer=setInterval(()=>{if(connected.value&&!busy.value)void query();},60000);
onUnmounted(()=>{clearInterval(monitorTimer);abort?.abort();});
</script>
<template>
 <div class="shell"><aside :class="{expanded:menuOpen}"><button class="mobile-menu" @click="menuOpen=!menuOpen" :aria-expanded="menuOpen">{{menuOpen?'收起导航':'展开导航'}}</button><div class="brand"><span class="logo">寰</span><div>寰瞰 <small>HUANKAN</small></div></div><p class="subtitle">全球金融智能情报平台</p><nav><template v-for="(menu,i) in menus" :key="menu"><p v-if="i===13" class="nav-label">研究与审核工具</p><button :class="{selected:active===menu}" @click="selectMenu(menu)" :disabled="unavailable.includes(menu)"><span aria-hidden="true">{{String(i+1).padStart(2,'0')}}</span>{{menu}}<small v-if="unavailable.includes(menu)">（未接入）</small></button></template></nav><div class="aside-note">事实有源 · 推断有界<br>本地研究工作台</div></aside>
 <main><header><div><small class="eyebrow">全球视野 / 原始证据</small><h1>{{active}}</h1></div><span class="connection">{{ practicalMode?queryStatus:'实时推送（SSE）：'+status }}</span></header>
 <div v-if="!connected" class="login panel"><h2>连接本地情报服务</h2><p v-if="!localAuto">旧入口的本机服务配置尚未加载。请使用免密产品入口。</p><p v-else>正在自动连接本机真实服务，无需填写访问密钥。</p><input v-if="!localAuto" v-model="token" type="password" autocomplete="off" placeholder="访问密钥" @keyup.enter="login"><button v-if="!localAuto" class="primary" :disabled="busy||!token" @click="login">{{busy?'正在连接…':'连接服务'}}</button><button v-if="localAuto&&!busy" class="primary" @click="login">重新连接</button><p>数据库、官方来源或 AI 尚未配置时，将显示实际状态。</p></div>
 <p v-if="error" role="alert" class="error">{{error}}</p>
 <template v-if="connected"><TransmissionDesk v-if="transmissionAvailable&&['金融事件研判','全球市场联动'].includes(active)" :token="token"/><template v-if="practicalMode"><PracticalDesk v-if="!(active==='全球宏观监测'&&macroChangesAvailable)" :key="route.path" :embedded="true" :token="token" @connection="queryStatus=$event"/><ResearchDesk v-if="active==='全球宏观监测'&&connected" :token="token" mode="全球宏观监测"/><details v-if="active==='全球宏观监测'&&macroChangesAvailable"><summary>既有宏观研究快照</summary><PracticalDesk :key="route.path" :embedded="true" :token="token" @connection="queryStatus=$event"/></details><details v-if="active==='数据源监控'"><summary>实时推送交付诊断</summary><BrowserObservation :token="token"/></details></template><template v-else><ImportantEvents v-if="active==='全球重要事件'" :token="token"/><WatchUpdates v-if="active==='智能机会雷达'" :token="token"/><FinancialWorkbench v-if="active==='智能机会雷达'" :token="token"/><FactEngineDesk v-if="active==='金融事实引擎'" :token="token"/><div class="metrics"><div v-for="[key,label] in [['official_message_count','官方来源消息'],['aggregated_lead_count','聚合发现线索'],['fact_verified_count','人工核实事件'],['macro_version_count','官方观测版本']]" :key="key" class="panel"><span>{{label}}</span><strong>{{stats[key]??'—'}}</strong><small>数据库实时查询</small></div></div>
 <section v-if="['全球实时情报','待核线索','全球企业公告','数据溯源中心'].includes(active)" class="panel feed"><div class="section-title"><h2>全球真实信息流</h2><label><input v-model="watchOnly" type="checkbox" @change="login">按我的关注名单推送</label><label>推送订阅 <select v-model="subscriptionScope" aria-label="推送订阅" @change="login"><option value="OFFICIAL">官方新增与修订</option><option value="LEADS">官方与待核线索</option><option value="HISTORY">允许回填投递（回填不提醒）</option></select></label><label>关注来源 <select v-model="subscriptionSource" aria-label="关注推送来源" @change="login"><option value="">全部已订阅来源</option><option v-for="s in sources.filter(s=>active==='全球企业公告'?s.id==='SEC':!['ECB_DATA','FRED','GLEIF'].includes(s.id))" :value="s.id">{{sourceName(s.id,s.name)}}</option></select></label><label>最低优先级 <select v-model.number="subscriptionPriority" aria-label="推送最低优先级" @change="login"><option :value="0">全部合格消息</option><option :value="50">50及以上</option><option :value="70">70及以上</option></select></label><label><input v-model="autoScroll" type="checkbox"> 自动滚动</label><label><input v-model="auto" type="checkbox"> 自动更新列表</label></div><div class="filters"><input v-model="search" placeholder="搜索原始标题" aria-label="搜索原始标题"><select v-model="source" aria-label="筛选来源"><option value="">全部官方来源</option><option v-for="s in sources.filter(s=>active==='全球企业公告'?s.id==='SEC':!['ECB_DATA','FRED','GLEIF'].includes(s.id))" :value="s.id">{{sourceName(s.id,s.name)}}</option></select><select v-model="region" aria-label="筛选国家"><option value="">全部国家或地区</option><option v-for="r in [...new Set(sources.map(s=>s.region))]" :key="r">{{r}}</option><option value="US">美国（GDELT位置代码）</option><option value="CH">中国（GDELT位置代码）</option><option value="GM">德国（GDELT位置代码）</option><option value="UK">英国（GDELT位置代码）</option></select><select v-model="category" aria-label="筛选类别"><option value="">全部类别</option><option v-for="c in ['官方新闻','管理层讲话','统计新闻','货币政策','聚合金融线索']" :key="c">{{c}}</option></select><select v-model="sort" aria-label="消息排序"><option value="official">官方来源优先</option><option value="published">发布时间</option><option value="firstSeen">首次发现时间</option></select><button :disabled="busy" @click="page=0;query()">查询</button><button :disabled="busy" @click="search='';source='';region='';category='';sort='official';page=0;query()">重置</button><button v-if="pending" @click="page=0;pending=0;query()">查看 {{pending}} 条更新通知</button></div>
 <div v-if="!events.length" class="empty"><h3>暂无真实数据</h3><p>请检查筛选条件、来源许可与采集任务。</p></div>
 <VirtualEvents ref="eventViewport" :items="events" v-slot="{event}"><article :data-event-id="event.id"><div class="meta"><span class="tag">{{sourceName(event.source_id,event.source_name)}}</span><span>{{event.level==='L2'?'聚合线索':'官方来源'}} · {{event.region}} · {{event.category}} · {{verified(event.verification_status)}}</span><span>{{event.published_at?'发布时间 '+time(event.published_at):'官方发布时间未知'}}</span></div><h3>{{title(event).text}}</h3><p class="muted">{{title(event).status}}</p><details><summary>查看官方原文与技术时间</summary><p class="original">{{event.original_title}}</p><p>官方发布时间 UTC：{{utc(event.published_at)}}</p><p>首次发现 UTC：{{utc(event.first_seen_at)}}</p><p>实际采集 UTC：{{utc(event.collected_at)}}</p><p>入库 UTC：{{utc(event.ingested_at)}}</p></details><p class="muted">{{kind(event.ingestion_kind)}} · {{freshness(event)}} · 首次发现 {{time(event.first_seen_at)}}<br>实际采集 {{time(event.collected_at)}} · 入库 {{time(event.ingested_at)}} · 版本 {{event.revision}}</p><p v-if="event.level==='L2'" class="muted">国家位置代码 {{event.countries||'未提供'}} · 机构索引 {{event.organizations||'未提供'}}<br>批次处理时间 {{time(event.batch_processed_at)}}（不是新闻发布时间）</p><p v-if="event.ingestion_kind==='NEW_EVENT'" class="muted">发现至入库 {{Number(event.discovery_to_ingest_ms).toFixed(0)}} 毫秒 · 首次服务端发送 {{time(event.first_server_sent_at)}}<br>发现至服务端收到确认 {{event.discovery_to_ack_ms==null?'尚无真实ACK':Number(event.discovery_to_ack_ms).toFixed(0)+' 毫秒'}}<br>Outbox创建 {{time(event.outbox_created_at)}} · 服务端收到确认 {{time(event.client_acknowledged_at)}}<br>客户端接收时间 {{time(event.client_received_at)}}（客户端时钟，未经跨端校准）</p><div class="article-foot"><span>来源：{{sourceName(event.source_id,event.source_name)}}</span><EventReadState :id="event.id" :version="event.collected_at"/><a v-if="event.level==='L0'" :href="'#/research?event='+event.id">查看金融事件研究详情</a><button @click="details(event.id)">查看证据</button><a v-if="safeOfficialUrl(event.source_url)" :href="event.source_url" target="_blank" rel="noopener noreferrer">查看原始来源 ↗</a></div></article></VirtualEvents><footer><button :disabled="page===0||busy" @click="page--;query()">上一页</button><span>第 {{page+1}} 页 · 共 {{total}} 条</span><button :disabled="(page+1)*50>=total||busy" @click="page++;query()">下一页</button></footer></section>
 <section v-else-if="active==='数据源监控'" class="panel feed"><h2>采集与授权状态</h2><p v-for="a in alerts" :key="a.source+a.message" class="error">{{a.source}}：{{a.message}} {{a.count??''}}</p><p v-if="!alerts.length">当前没有触发运行告警；无新公告不等于连接失败。</p><article v-for="s in sources" :key="s.id"><h3>{{sourceName(s.id,s.name)}} <span class="tag">{{s.enabled?'已启用':'未启用'}}</span></h3><p>{{s.region}} · 来源等级 {{s.level}} · 每 {{duration(s.interval_seconds)}} 检查</p><p>最近检查 {{time(s.last_check)}} · 最近成功 {{time(s.last_success)}}<br>最近真实新事件 {{s.last_new_event?time(s.last_new_event):'等待真实样本'}} · 实际事件 {{s.real_records}}<br>请求成功率 {{s.success_rate==null?'暂无样本':(s.success_rate*100).toFixed(1)+'%'}} · 平均响应 {{s.average_response_ms==null?'暂无样本':Number(s.average_response_ms).toFixed(0)+' 毫秒'}}<br>连续失败 {{s.consecutive_failures}} · 失败任务 {{s.failed_tasks}} · HTTP错误 {{s.error_count}} · 全局SSE服务端异常 {{s.sse_failures}} · 未显式确认 {{s.sse_unacknowledged}} · 补读发送 {{s.sse_replayed}} · 旧记录未分类 {{s.sse_unclassified_failures}}<br>真实新增发现延迟 P50 / P95：{{s.new_latency_samples>=20?s.discovery_p50_ms+' / '+s.discovery_p95_ms+' 毫秒':'等待真实新增事件样本（不足20条时不输出P95）'}}</p><p v-if="s.check_overdue||s.license_expired||s.consecutive_failures>=3||s.http_status===429" class="error">{{s.license_expired?'许可已失效； ':''}}{{s.check_overdue?'检查超过预期间隔； ':''}}{{s.consecutive_failures>=3?'连续采集失败； ':''}}{{s.http_status===429?'官方接口限流':''}}</p><p v-if="s.id==='GDELT'">最新批次 {{s.gdelt_latest_batch}} · {{availability(s.gdelt_availability)}}<br>已完成游标 {{s.gdelt_completed_cursor}} · 历史缺口 {{s.gdelt_missing_batches}}</p><p>检查时效：{{!s.enabled?'未启用':s.check_overdue?'检查已超期':'检查间隔内'}} · 最近异常 {{time(s.last_error_at)}} {{s.last_error_detail||''}}</p><p>许可：{{s.license_status==='APPROVED'?'已记录核验（限定用途）':'待核验或禁用'}} · 最近任务：{{jobState(s.job_status)}}</p><p>开始 {{time(s.started_at)}} · 实际解析 {{s.fetched_count??'—'}} · 新增 {{s.new_count??'—'}} · 重复记录 {{s.duplicate_count??'—'}} · 重复批次 {{s.duplicate_batch_count??'—'}} · 隔离 {{s.quarantine_count??'—'}} · 耗时 {{s.duration_ms??'—'}} 毫秒</p><p v-if="s.error_code">采集失败：{{s.error_code==='PARSE_OR_QUALITY_FAILURE'?'解析或质量校验失败':'HTTP或存储失败'}}（HTTP {{s.http_status??'未取得响应'}}） · {{s.error_detail}}</p><a :href="s.terms_url" target="_blank" rel="noopener noreferrer">查看许可依据 ↗</a><button :disabled="busy||!s.enabled||s.license_status!=='APPROVED'||!['FED','ECB','GDELT','SEC','NBS','ECB_DATA'].includes(s.id)" @click="collect(s.id)">执行采集</button></article></section>
 <section v-else-if="active==='系统设置'" class="panel feed"><h2>本地服务设置</h2><p>AI 翻译与分析：尚未配置</p><p>实时证券行情：未取得授权，未接入</p><p>后台采集：由服务环境变量和数据库来源许可共同控制</p><h3>SEC 官方公司关注</h3><p>{{secStatus.state||'待配置'}} · 官方映射 {{secStatus.mapping_count??0}} 条 · 获取时间 {{time(secStatus.mapping_acquired_at)}}</p><p>在本地设置 SEC_CONTACT_EMAIL、SEC_USER_AGENT、SEC_FOLLOWED_CIKS 和 SEC_ENABLED；无需登录密码或 API Key。</p><button :disabled="!secStatus.contact_configured" @click="secAction('companies/refresh')">更新官方公司映射</button><p>候选关注对象：英伟达、AMD、博通、微软、苹果。获取官方映射后搜索添加；尚未自动关注任何公司。</p><input v-model="secSearch" placeholder="公司名称或证券代码"><button @click="secAction('companies/search',{search:secSearch})">搜索公司</button><p v-for="c in secCompanies" :key="c.cik">{{c.title}} · {{c.ticker}} · CIK {{c.cik}} <button @click="secAction('companies/follow',{cik:c.cik})">添加关注</button></p><p v-for="c in secStatus.followed||[]" :key="c.cik">已关注：{{c.title}} · {{c.ticker}}</p><h3>FRED经济序列</h3><p>{{fredStatus.state||'待配置'}} · 实际请求 {{fredStatus.requests??0}} 次 · 证据 {{fredStatus.evidence??0}} 条</p><p>在本地设置 FRED_API_KEY、FRED_SERIES_WHITELIST 和 FRED_ENABLED；逐序列核验许可后启用。</p><button @click="logout">断开连接并清除密钥</button></section>
 <MarketLinkage v-else-if="active==='全球市场联动'" :token="token"/><GovernanceDesk v-else-if="active==='全球金融总览'" :token="token"/><ResearchDesk v-else-if="['全球宏观监测','事件关联研究','事件审核队列'].includes(active)" :token="token" :mode="active"/>
 <section v-else class="panel empty"><h2>该模块尚未接入</h2><p>需要通过真实数据、来源许可和自动化测试门禁后启用。</p></section>
 <BrowserObservation v-if="connected&&active==='数据源监控'" :token="token"/><section v-if="evidence.length" class="panel feed"><div class="section-title"><h2>原始证据版本</h2><button @click="evidence=[]">关闭</button></div><article v-for="e in evidence" :key="e.id"><h3>版本 {{e.revision}} · {{verified(e.verification_status)}} · {{kind(e.ingestion_kind)}}</h3><p>文档标识：{{e.source_document_id}}</p><p>发布：{{time(e.published_at)}} · 采集：{{time(e.collected_at)}} · 入库：{{time(e.ingested_at)}}</p><p>来源身份 {{e.source_identity==='OFFICIAL_SOURCE_CONFIRMED'?'官方来源证据确认':'聚合来源确认'}} · 文件完整性 {{e.integrity==='HASH_CONFIRMED'?'哈希确认':'待核验'}}<br>事件事实核验：待核验 · 独立证据验证：待核验 · 许可 {{e.license_status==='APPROVED'?'限定用途已核验':'待核验'}}</p><p v-if="e.canonical_source_url!==e.original_source_url">规范URL：{{e.canonical_source_url}}（{{e.canonical_equivalence_confirmed?'等价已实测':'等价尚未确认，不用于合并事件'}}）</p><p>原始字节：{{e.raw_bytes}} · 解析器 {{e.parser_version}}</p><code>SHA-256 {{e.raw_content_hash}}</code><p><a v-if="safeOfficialUrl(e.source_url)" :href="e.source_url" target="_blank" rel="noopener noreferrer">查看官方来源 ↗</a></p><p v-if="e.batch_id">GDELT 批次 {{e.batch_id}} · 主题 {{e.themes}}<br>机构 {{e.organizations}} · 国家位置代码 {{e.countries}}<br><a v-if="safeArticleUrl(e.underlying_url)" :href="e.underlying_url" target="_blank" rel="noopener noreferrer">查看未核实的新闻原文 ↗</a></p></article></section></template></template><details class="abbreviations"><summary>技术缩写说明</summary><p>人工智能（AI）；实时推送（SSE）；接收确认（ACK）；事务消息发件箱（Outbox）；全球法人识别编码（LEI）；财报结构化格式（XBRL）；内容哈希算法（SHA-256）。这些技术状态不等同于事实核验通过。</p></details><div class="bottom-note">原始事实与 AI 推断分离 · 所有时间按北京时间显示 · 本系统用于信息研究</div>
 </main></div>
</template>













